import React, { useState } from "react";
import styled from "styled-components";
import SdmsResource from "../../resource/id";
import Button from "../../../Common/components/button";
import ProjectResource from "../../../Root/resource/id";
import { getProjectTypeState } from "../../../Root/resource/projectType";
import AccountResource from "../../../Account/resource/id";

const QuickMenuBar = (props) => {
    const [toggleBtnOpen, setToggleBtnOpen] = useState(false);
    const projectTypeState = getProjectTypeState();

    const getQuickButtonClassName = (name) =>
        props.visiblePopups?.[name] ? 'on' : 'off';

    const toggle = () => setToggleBtnOpen(v => !v);

    if (props.isEditMode) {
        return (
            <QuickMenuBarComponent>
                <MenuItem onClick={() => props.setVisiblePopups(SdmsResource.ID.menu.editMode_poi, true)}>
                    <Inner $position="left" className={getQuickButtonClassName(SdmsResource.ID.menu.editMode_poi)}>
                        <EditPoiIcon />
                        <Text>{SdmsResource.ID.menu.editMode_poi}</Text>
                    </Inner>
                </MenuItem>
                <MenuItem onClick={() => props.setVisiblePopups(SdmsResource.ID.menu.editMode_fakeWall, true)}>
                    <Inner $position="center" className={getQuickButtonClassName(SdmsResource.ID.menu.editMode_fakeWall)}>
                        <EditFakeWallIcon />
                        <Text>{SdmsResource.ID.menu.editMode_fakeWall}</Text>
                    </Inner>
                </MenuItem>
                <MenuItem onClick={() => props.setVisiblePopups(SdmsResource.ID.menu.editMode_areaName, true)}>
                    <Inner $position="right" className={getQuickButtonClassName(SdmsResource.ID.menu.editMode_areaName)}>
                        <EditAreaNameIcon />
                        <Text>{SdmsResource.ID.menu.editMode_areaName}</Text>
                    </Inner>
                </MenuItem>
            </QuickMenuBarComponent>
        );
    }
    else if (props.controlMode === SdmsResource.controlMode.integrated) {
        return (
            <>
                <QuickMenuBarComponent>
                    <MenuItem onClick={() => props.setVisiblePopups(SdmsResource.ID.menu.statusInfo)}>
                        <Inner $position="left" className={getQuickButtonClassName(SdmsResource.ID.menu.statusInfo)}>
                            <StatusInfoIcon />
                            <Text>{SdmsResource.ID.menu.statusInfo}</Text>
                        </Inner>
                    </MenuItem>
                    <MenuItem onClick={() => props.setVisiblePopups(SdmsResource.ID.menu.dashboard)}>
                        <Inner $position="center" className={getQuickButtonClassName(SdmsResource.ID.menu.dashboard)}>
                            <DashboardIcon />
                            <Text>{SdmsResource.ID.menu.dashboard}</Text>
                        </Inner>
                    </MenuItem>
                    <MenuItem onClick={() => props.setVisiblePopups(SdmsResource.ID.menu.event)}>
                        <Inner $position="center" className={getQuickButtonClassName(SdmsResource.ID.menu.event)}>
                            <EventIcon />
                            <Text>{SdmsResource.ID.menu.event}</Text>
                        </Inner>
                    </MenuItem>
                    <MenuItem onClick={() => props.setVisiblePopups(SdmsResource.ID.menu.manualReport)}>
                        <Inner $position={projectTypeState.isNormal ? 'center' : 'right'} className={getQuickButtonClassName(SdmsResource.ID.menu.manualReport)}>
                            <ManualReportIcon />
                            <Text>{SdmsResource.ID.menu.manualReport}</Text>
                        </Inner>
                    </MenuItem>
                    {projectTypeState.isNormal &&
                        <MenuItem onClick={() => props.setVisiblePopups(SdmsResource.ID.menu.workerInfo)}>
                            <Inner $position="right" className={getQuickButtonClassName(SdmsResource.ID.menu.workerInfo)}>
                                <WorkerInfoIcon />
                                <Text>{SdmsResource.ID.menu.workerInfo}</Text>
                            </Inner>
                        </MenuItem>
                    }
                    {/* <MenuItem onClick={() => props.setVisiblePopups(SdmsResource.ID.menu.accessInfo)}>
                        <Inner $position="right" className={getQuickButtonClassName(SdmsResource.ID.menu.accessInfo)}>
                            <AccessInfoIcon />
                            <Text>{SdmsResource.ID.menu.accessInfo}</Text>
                        </Inner>
                    </MenuItem> */}
                    {/* <MenuItem onClick={() => props.setVisiblePopups(SdmsResource.ID.menu.sumpInfo)}>
                        <Inner $position="right" className={getQuickButtonClassName(SdmsResource.ID.menu.sumpInfo)}>
                            <SumpInfoIcon />
                            <Text>{SdmsResource.ID.menu.sumpInfo}</Text>
                        </Inner>
                    </MenuItem> */}
                </QuickMenuBarComponent>
                <ModeToggleComponent>
                    <button
                        type="button"
                        aria-expanded={toggleBtnOpen}
                        onClick={toggle}
                        className={toggleBtnOpen ? 'on' : null}
                    >
                        <ModeToggleIcon />
                        모드 변경
                    </button>

                    <ul hidden={!toggleBtnOpen}>
                        {!projectTypeState.isFacilityProject &&
                            <li>
                                <Button 
                                    variant="outline" 
                                    size="sm"
                                    onClick={() => {
                                        props.handleControlMode(SdmsResource.controlMode.simulation, true);
                                        setToggleBtnOpen(false);
                                    }}
                                >
                                    누출 확산 시뮬레이션
                                </Button>
                            </li>
                        }
                        <li>
                            <Button 
                                variant="outline" 
                                size="sm"
                                onClick={() => {
                                    props.handleControlMode(SdmsResource.controlMode.equipment, true);
                                    setToggleBtnOpen(false);
                                }}
                            >
                                설비모드
                            </Button>
                        </li>
                        {
                            !projectTypeState.isFacilityProject &&
                            ProjectResource.getUserInfo()?.grad_sn !== AccountResource.accountLevelNo.user &&
                                <li>
                                    <Button 
                                        variant="outline" 
                                        size="sm"
                                        onClick={() => {
                                            props.handleControlMode(SdmsResource.controlMode.editMode, [true, SdmsResource.ID.menu.editMode_poi, SdmsResource.ID.poi_editSubMenu.none]);
                                            setToggleBtnOpen(false);
                                        }}
                                    >
                                        편집모드
                                    </Button>
                                </li>
                        }
                    </ul>
                </ModeToggleComponent>
            </>
        );
    } 
    // else if (props.controlMode === SdmsResource.controlMode.equipment) {
    //     return (
    //         <QuickMenuBarComponent>
    //             <MenuItem onClick={() => props.setVisiblePopups(SdmsResource.ID.menu.statusInfo)}>
    //                 <Inner $position="left" className={getQuickButtonClassName(SdmsResource.ID.menu.statusInfo)}>
    //                     <StatusInfoIcon />
    //                     <Text>{SdmsResource.ID.menu.statusInfo}</Text>
    //                 </Inner>
    //             </MenuItem>
    //             <MenuItem onClick={() => props.setVisiblePopups(SdmsResource.ID.menu.dashboard)}>
    //                 <Inner $position="center" className={getQuickButtonClassName(SdmsResource.ID.menu.dashboard)}>
    //                     <DashboardIcon />
    //                     <Text>{SdmsResource.ID.menu.dashboard}</Text>
    //                 </Inner>
    //             </MenuItem>
    //             <MenuItem onClick={() => props.setVisiblePopups(SdmsResource.ID.menu.event)}>
    //                 <Inner $position="center" className={getQuickButtonClassName(SdmsResource.ID.menu.event)}>
    //                     <EventIcon />
    //                     <Text>{SdmsResource.ID.menu.event}</Text>
    //                 </Inner>
    //             </MenuItem>
    //             <MenuItem onClick={() => props.handleControlMode(SdmsResource.controlMode.integrated)}>
    //                 <InnerEdit>
    //                     <IntegratedModeIcon />
    //                     <Text>{SdmsResource.ID.menu.integrated}</Text>
    //                 </InnerEdit>
    //             </MenuItem>
    //         </QuickMenuBarComponent>
    //     );
    // } 

    return null;
};

const QuickMenuBarComponent = styled.div`
    background: ${({ theme }) => theme.colors.background.base};
    border-radius: 8px;
    position: absolute;
    left: 50%;
    bottom: 20px;
    transform: translate(-50%, 0);
    box-shadow: 0 0 5px 0 rgba(0, 0, 0, 0.06), 0 10px 17px 0 rgba(0, 0, 0, 0.18);
    ${({ theme }) => theme.mixins.flex('center', 'center')}
    z-index: 2;
`;

const MenuItem = styled.div`
    position: relative;
    height: 52px;
    /* transition: background 0.3s ease, height 0.3s ease, transform 0.3s ease; */
`;

const InnerEdit = styled.div`
    position: relative;
    height: 52px;
    padding: 12px 20px;
    background: ${({ theme }) => theme.colors.primary.p500};
    border-radius: 0 8px 8px 0;
    ${({ theme }) => theme.mixins.flex('center', 'center')}
    cursor: pointer;
    transition: background 0.3s ease, height 0.3s ease, transform 0.3s ease;

    &:hover {
        background: ${({ theme }) => theme.colors.primary.p600};

        span {
            color: ${({ theme }) => theme.colors.white} !important;
        }
    }
`;

const Inner = styled.div`
    position: relative;
    height: 52px;
    padding: 12px 20px;
    background: ${({ theme }) => theme.colors.background.base};
    ${({ theme }) => theme.mixins.flex('center', 'center')}
    cursor: pointer;
    /* transition: background 0.3s ease, height 0.3s ease, transform 0.3s ease; */

    border-radius: ${({ $position }) =>
        $position === 'left' ? '8px 8px 0 8px' :
            $position === 'right' ? '8px 8px 8px 0' : '8px 8px 0 0'};

    &:hover, &.on {
        height: 60px;
        transform: translateY(-8px);
        border-bottom: 3px solid ${({ theme }) => theme.colors.primary.p500};
        z-index: 2;
    }

    &.on > svg {
        filter: invert(44%) sepia(50%) saturate(6689%) hue-rotate(217deg) brightness(99%) contrast(100%);
    }

    svg {
        opacity: 1;
        transition: opacity 0.3s ease, transform 0.3s ease;
    }

    span {
        opacity: 0;
        transform: scale(0.8);
        position: absolute;
        transition: opacity 0.3s ease, transform 0.3s ease;
        color: ${({ theme }) => theme.colors.grayscale.g100};
        font-size: 0.75rem;
        font-weight: 500;
    }

    &:hover svg {
        opacity: 0;
        transform: scale(0.8);
    }

    &:hover span {
        opacity: 1;
        transform: scale(1);
    }
`;

const Icon = styled.svg`
    opacity: 1;
    transform: scale(1);
    transition: opacity 0.3s ease, transform 0.3s ease;

    ${MenuItem}:hover & {
        opacity: 0;
        transform: scale(0.8);
    }
`;

const Text = styled.span`
    opacity: 0;
    transform: scale(0.8);
    position: absolute;
    transition: opacity 0.3s ease, transform 0.3s ease;
    color: ${({ theme }) => theme.colors.grayscale.g100};
    font-size: 0.75rem;
    font-weight: 500;
    line-height: 170%;
    letter-spacing: -0.36px;
    text-align: center;
    white-space: pre-line;

    ${MenuItem}:hover & {
        opacity: 1;
        transform: scale(1);
    }
`;

const ModeToggleComponent = styled.div`
    position: absolute;
    right: 20px;
    bottom: 20px;
    z-index: 2;

    > button {
        ${({ theme }) => theme.mixins.flex('center', 'center')};
        flex-shrink: 0;
        width: 52px;
        height: 52px;
        border-radius: 999px;
        border: 1px solid ${({ theme }) => theme.colors.grayscale.g100} !important;
        background: ${({ theme }) => theme.colors.white};
        box-shadow: 0 0 5px 0 rgba(0, 0, 0, 0.08), 0 10px 28px 0 rgba(0, 0, 0, 0.22);
        text-indent: -9999px;
        transition: color .15s ease, background .15s ease, border-color .15s ease, box-shadow .15s ease;

        color: ${({ theme }) => theme.colors.grayscale.g300};

        > svg { display: block; }
        > svg path { fill: currentColor; }

        &:hover {
            border-color: ${({ theme }) => theme.colors.grayscale.g150} !important;
            background: ${({ theme }) => theme.colors.grayscale.g50};
            color: ${({ theme }) => theme.colors.primary.p500};
        }

        &:active,
        &.on {
            border-color: ${({ theme }) => theme.colors.grayscale.g300} !important;
            background: ${({ theme }) => theme.colors.grayscale.g75};
            color: ${({ theme }) => theme.colors.primary.p700};
        }
    }

    > ul {
        position: absolute;
        right: 0;
        bottom: 68px;

        &[hidden] { 
            display: none; 
        }

        li {
            width: 150px;

            &:not(:last-child) {
                margin-bottom: 8px;
            }

            > button {
                width: 100%;
                white-space: nowrap;
            }
        }
    }
`;

